#include <bits/stdc++.h>
using namespace std;

int main() {
    long long k;
    int n;
    scanf("%lld %d", &k, &n);
    vector<int> deg(n, 0);
    for (int i = 0; i < n - 1; i++) {
        int a, b;
        scanf("%d %d", &a, &b);
        deg[a - 1]++;
        deg[b - 1]++;
    }
    const long long MOD = 1000000007;
    long long ans = k % MOD;
    // Root's children avoid the root; other children avoid their parent and grandparent.
    // Siblings must also differ, giving a falling factorial per node.
    for (int v = 0; v < n; v++) {
        long long available = k - (v == 0 ? 1 : 2);
        long long children = max(0, v == 0 ? deg[v] : deg[v] - 1);
        if (available < children) { puts("0"); return 0; }
        for (long long j = 0; j < children; j++) ans = ans * ((available - j) % MOD) % MOD;
    }
    printf("%lld\n", ans);
}

import java.io.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        if (c == -1) return null;
        ByteArrayOutputStream sb = new ByteArrayOutputStream();
        while (c != -1 && c > ' ') { sb.write(c); c = read(); }
        return sb.toString(java.nio.charset.StandardCharsets.UTF_8);
    }

    public static void main(String[] args) throws IOException {
        long k = nextLong();
        int n = nextInt();
        int[] deg = new int[n];
        for (int i = 0; i < n - 1; i++) {
            deg[nextInt() - 1]++;
            deg[nextInt() - 1]++;
        }
        final long MOD = 1000000007L;
        long ans = k % MOD;
        // Root's children avoid the root; other children avoid their parent and grandparent.
        // Siblings must also differ, giving a falling factorial per node.
        for (int v = 0; v < n; v++) {
            long available = k - (v == 0 ? 1 : 2);
            long children = Math.max(0, v == 0 ? deg[v] : deg[v] - 1);
            if (available < children) { System.out.println(0); return; }
            for (long j = 0; j < children; j++) ans = ans * ((available - j) % MOD) % MOD;
        }
        System.out.println(ans);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' || c == '\t' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func readToken() string {
	c, err := rd.ReadByte()
	for err == nil && (c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		c, err = rd.ReadByte()
	}
	if err != nil {
		return ""
	}
	b := []byte{}
	for err == nil && !(c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		b = append(b, c)
		c, err = rd.ReadByte()
	}
	return string(b)
}

func main() {
	k, n := readInt(), readInt()
	deg := make([]int, n)
	for i := 0; i < n-1; i++ {
		deg[readInt()-1]++
		deg[readInt()-1]++
	}
	const MOD = 1000000007
	ans := k % MOD
	// Root's children avoid the root; other children avoid their parent and grandparent.
	// Siblings must also differ, giving a falling factorial per node.
	for v := 0; v < n; v++ {
		available, children := k-2, deg[v]-1
		if v == 0 {
			available, children = k-1, deg[v]
		}
		children = max(0, children)
		if available < children {
			fmt.Println(0)
			return
		}
		for j := 0; j < children; j++ {
			ans = ans * ((available - j) % MOD) % MOD
		}
	}
	fmt.Println(ans)
}
